import io,json,time
from contextlib import redirect_stdout
from pathlib import Path
from unittest.mock import patch
from card_market_tracker.watchlist_alerts import application as app,cli
budget=cli.Budget(5)
events=[]
first=[]
class Output(io.StringIO):
    def write(self,text):
        if text and not first:
            first.append(time.monotonic()<budget.deadline)
        return super().write(text)
class Logger:
    def log(self,*args,**kwargs):
        assert first, 'completion_before_stdout'
        events.append(kwargs['extra'])
        budget.deadline=time.monotonic()-1
with patch.object(cli.logging,'getLogger',return_value=Logger()),redirect_stdout(Output()) as output:
    code=cli._report({'version':1,'operation':'verify','result':'ok','level':'local','counts':{'alerts':0,'evidence':0}},'verify',time.perf_counter(),0,budget=budget)
assert code==0 and first==[True] and len(events)==1 and events[0]['result']=='ok','first_write_or_log_count'
assert json.loads(output.getvalue())['result']=='ok','stdout_success'
expired=app.Budget(5)
read_calls=[]
def read(*args,**kwargs):
    assert kwargs['revision']==1 and 0<kwargs['timeout']<=5,'residual_read'
    read_calls.append(1)
    expired.deadline=time.monotonic()-1
    return {'entry':{}}
def forbidden_parse(*args,**kwargs):
    raise AssertionError('parse_before_immediate_deadline_check')
with patch.object(app.watchlist_storage,'get',read),patch.object(app.watchlist_validation,'parse_entry',forbidden_parse):
    try:
        app._origin_entry(Path('unused.sqlite'),{},'wlt1_'+'0'*64,1,expired)
    except Exception as error:
        assert getattr(error,'category',None)=='storage_timeout','post_read_deadline_category'
    else:
        raise AssertionError('post_read_deadline_accepted')
assert read_calls==[1],'exactly_one_original_read'
print(json.dumps({'status':'pass','success_first_stdout_within_budget':first[0],'success_completion_events':len(events),'completion_after_stdout':True,'immediate_post_get_timeout_before_parse':True},sort_keys=True))
